-- The property contract: every control maps to a property here, a widget in
-- GUI2D/hdgui_2D.lua and a node in GUI2D/device_2D.lua.
-- Generated by `rebench new`: a stereo effect with one Level knob.

format_version = "3.0"

audio_inputs = {
  inLeft  = jbox.audio_input { ui_name = jbox.ui_text("audio_in_left") },
  inRight = jbox.audio_input { ui_name = jbox.ui_text("audio_in_right") },
}

audio_outputs = {
  outLeft  = jbox.audio_output { ui_name = jbox.ui_text("audio_out_left") },
  outRight = jbox.audio_output { ui_name = jbox.ui_text("audio_out_right") },
}

custom_properties = jbox.property_set {
  document_owner = {
    properties = {
      level = jbox.number {
        property_tag = 1,
        default = 0.5,             -- normalised; 0.5 = unity gain
        ui_name = jbox.ui_text("level"),
        ui_type = jbox.ui_percent { decimals = 0 },
      },
    },
  },

  rtc_owner = {
    properties = {
      instance = jbox.native_object {},
    },
  },
}

remote_implementation_chart = {
  ["/custom_properties/level"] = {
    internal_name    = "Level",
    short_ui_name    = jbox.ui_text("level_short"),
    shortest_ui_name = jbox.ui_text("level_shortest"),
  },
}

midi_implementation_chart = {
  midi_cc_chart = {
    [12] = "/custom_properties/level",
  },
}

jbox.add_stereo_audio_routing_pair {
  left  = "/audio_inputs/inLeft",
  right = "/audio_inputs/inRight",
}

jbox.add_stereo_audio_routing_pair {
  left  = "/audio_outputs/outLeft",
  right = "/audio_outputs/outRight",
}

jbox.add_stereo_effect_routing_hint {
  type = "true_stereo",
  left_input   = "/audio_inputs/inLeft",
  right_input  = "/audio_inputs/inRight",
  left_output  = "/audio_outputs/outLeft",
  right_output = "/audio_outputs/outRight",
}

jbox.add_stereo_audio_routing_target {
  signal_type = "normal",
  left  = "/audio_inputs/inLeft",
  right = "/audio_inputs/inRight",
  auto_route_enable = true,
}

jbox.add_stereo_audio_routing_target {
  signal_type = "normal",
  left  = "/audio_outputs/outLeft",
  right = "/audio_outputs/outRight",
  auto_route_enable = true,
}

jbox.set_effect_auto_bypass_routing {
  { "/audio_inputs/inLeft",  "/audio_outputs/outLeft" },
  { "/audio_inputs/inRight", "/audio_outputs/outRight" },
}
